-- Dollar-weighted initial denial rate (%) for medical claims first adjudicated in 2029: per claim_id take the earliest medical_claims adjudication row (event_date, non-reversal first, then record_id); population = claims whose first adjudication event_date is 2029-01-01..2029-12-31; rate = 100 * billed_cents of claims whose first adjudication status is 'denied' / billed_cents of all such claims. 2 dp.
WITH c AS MATERIALIZED (SELECT json_extract(payload,'$.claim_id') cid, json_extract(payload,'$.status') st, json_extract(payload,'$.event_date') d, json_extract(payload,'$.record_id') rid, json_extract(payload,'$.billed_cents') b FROM records
  WHERE stream='medical_claims' AND json_extract(payload,'$.claim_id') IS NOT NULL),
f AS (SELECT * FROM (SELECT *, row_number() OVER (PARTITION BY cid ORDER BY d, CASE st WHEN 'reversed' THEN 1 ELSE 0 END, rid) rn FROM c) WHERE rn=1)
SELECT ROUND(100.0*SUM(CASE WHEN st='denied' THEN b ELSE 0 END)/SUM(b),2) AS value FROM f WHERE d BETWEEN '2029-01-01' AND '2029-12-31';
